 static byte[] Mesh(){var result=new byte[3*72+3*4];for(int i=0;i<3;i++){Buffer.BlockCopy(BitConverter.GetBytes((float)i),0,result,i*72,4);for(int c=3;c<18;c++)Buffer.BlockCopy(BitConverter.GetBytes(.25f),0,result,i*72+c*4,4);}for(int i=0;i<3;i++)Buffer.BlockCopy(BitConverter.GetBytes(i),0,result,3*72+i*4,4);return result;}
 static SceneSnapshot Snapshot(long revision,long sequence,long epoch=1)=>new SceneSnapshot(revision,sequence,new[]{new SceneObject(1,"node",0,new JObject{{"resource_epoch",epoch}})});
 static void Bridge(){using(var domain=new OwnedDomain(Guid.NewGuid(),1)){var identity=new SessionIdentity(domain.Instance,domain.Generation,SceneCommandCatalog.Digest);using(var host=new MirrorVmHost(domain,identity,Snapshot(1,1))){var node=host.ResolveId(1,"node");host.BeginTick(new TickInput(1,Snapshot(1,1)));var counts=domain.Array("i32",new object[]{3});int request=(int)host.Call("SpatialWallpaper.Sdk::SceneResources::BeginMesh(Node,System.Int32,System.Int32[])->System.Int32",null,new object[]{node,3,counts});Yes(request==1,"real native author binding creates request");Yes((int)host.Call("SpatialWallpaper.Sdk::SceneResources::State(System.Int32)->System.Int32",null,new object[]{request})==1,"Begin does not fabricate Ready");var batch=host.EndTick();Yes(batch.Commands.Single().Operation=="Resource"&&SceneCommandProtocol.Decode(SceneCommandProtocol.Encode(batch),identity).Commands.Single().Arguments[2].ToString()=="begin_mesh","real protocol roundtrip begin");var results=new System.Collections.Generic.Dictionary<long,JToken>{{-request,new JObject{{"state",1},{"error",JValue.CreateNull()},{"epoch",1}}}};var ack=new BatchAck(identity,1,1,true,Snapshot(1,2),results:results);host.ApplyAck(ScriptWire.Ack(ScriptWire.Ack(ack),identity));host.BeginTick(new TickInput(2,Snapshot(1,2)));batch=host.EndTick();Yes((string)batch.Commands.Single().Arguments[2]=="poll","empty author tick polls actual renderer");results[-request]=new JObject{{"state",2},{"error",JValue.CreateNull()},{"epoch",1}};host.ApplyAck(new BatchAck(identity,2,2,true,Snapshot(1,3),results:results));host.BeginTick(new TickInput(3,Snapshot(1,3)));Yes((int)host.Call("SpatialWallpaper.Sdk::SceneResources::State(System.Int32)->System.Int32",null,new object[]{request})==2,"synthetic renderer Ready only after ACK, not GPU acceptance test");host.Call("SpatialWallpaper.Sdk::SceneResources::Apply(System.Int32)->System.Void",null,new object[]{request});batch=host.EndTick();Yes(SceneCommandProtocol.AdvancesRevision(batch),"explicit publication advances revision");results[-request]=new JObject{{"state",4},{"error","revoked"},{"epoch",2}};host.ApplyAck(new BatchAck(identity,3,3,true,Snapshot(2,4,2),results:results));host.BeginTick(new TickInput(4,Snapshot(2,4,2)));Yes((int)host.Call("SpatialWallpaper.Sdk::SceneResources::State(System.Int32)->System.Int32",null,new object[]{request})==4,"revoked ACK cannot revive ready resource");No(()=>host.Call("SpatialWallpaper.Sdk::SceneResources::Apply(System.Int32)->System.Void",null,new object[]{request}),"old result publication denied");host.Call("UnityEngine.CoreModule::UnityEngine.GameObject::SetActive(System.Boolean)->System.Void",node,new object[]{false});Yes(host.EndTick().Commands.Single().Operation=="SetActive","precise native node SetActive VM dispatch");}}}
 static int Main(){Bridge();var session=Guid.NewGuid();using(var ledger=new ResourceLedger(new ResourceCost(8388608,8388608,8388608,16)))using(var inbox=new NativeUploadInbox(session,7,4,ledger)){
  int[] counts={3,3};var spec=NativeUploadSpec.Mesh(3,counts);counts[0]=999;Yes(spec.SubmeshIndices[0]==3&&spec.SubmeshIndices.Count==2&&spec.Bytes==3*72+6*4,"immutable full-stream multi-submesh metadata");No(()=>NativeUploadSpec.Mesh(3,4),"triangles");No(()=>NativeUploadSpec.Texture(513,512),"texture cap");No(()=>inbox.Begin(Guid.NewGuid(),7,4,spec),"foreign session");No(()=>inbox.Begin(session,8,4,spec),"foreign generation");long token=inbox.Begin(session,7,4,NativeUploadSpec.Mesh(3,3));var bytes=Mesh();No(()=>inbox.Append(token,4,1,bytes),"out of order");No(()=>inbox.Append(token,4,0,new byte[65537]),"chunk cap");inbox.Append(token,4,0,bytes);No(()=>inbox.Append(token,4,0,new byte[1]),"duplicate block");inbox.Seal(token,4);Yes(inbox.State(token)==NativeUploadPhase.Queued,"real queued before renderer upload");No(()=>inbox.Append(token,4,bytes.Length,new byte[1]),"sealed mutation");long invalid=inbox.Begin(session,7,4,NativeUploadSpec.Mesh(3,3));bytes=Mesh();Buffer.BlockCopy(BitConverter.GetBytes(float.NaN),0,bytes,40,4);inbox.Append(invalid,4,0,bytes);No(()=>inbox.Seal(invalid,4),"UV NaN admission");inbox.Cancel(invalid,4);long index=inbox.Begin(session,7,4,NativeUploadSpec.Mesh(3,3));bytes=Mesh();Buffer.BlockCopy(BitConverter.GetBytes(3),0,bytes,216,4);inbox.Append(index,4,0,bytes);No(()=>inbox.Seal(index,4),"invalid index");inbox.Cancel(index,4);long incomplete=inbox.Begin(session,7,4,NativeUploadSpec.Texture(4,4));No(()=>inbox.Seal(incomplete,4),"incomplete texture");inbox.Revoke(5);Yes(inbox.State(token)==NativeUploadPhase.Canceled,"revocation cancels queued candidate");No(()=>inbox.Append(incomplete,4,0,new byte[64]),"old authority block");No(()=>inbox.Seal(token,4),"old authority result");No(()=>inbox.Revoke(4),"epoch regression");long fresh=inbox.Begin(session,7,5,NativeUploadSpec.Texture(4,4));inbox.Append(fresh,5,0,new byte[64]);inbox.Seal(fresh,5);Yes(inbox.State(fresh)==NativeUploadPhase.Queued,"fresh epoch accepted");Yes(ledger.Used.ManagedBytes>0,"canceled in-flight staging not refunded before renderer cleanup");}
 using(var small=new ResourceLedger(new ResourceCost(100,100,100,1)))using(var denied=new NativeUploadInbox(session,1,1,small)){No(()=>denied.Begin(session,1,1,NativeUploadSpec.Texture(8,8)),"budget denial");Yes(small.Used.ManagedBytes==0,"budget denial no partial charge");}Console.WriteLine("native dynamic upload checks passed: "+checks);return 0;
 }
